// _vector_comparePtrInt32 returns -1, 0 or +1 as the map key a sorts before,
// with or after b, two keys of type *int32.
func _vector_comparePtrInt32(a, b *int32) int {
	if a == nil || b == nil {
		return wire.CompareBool(a != nil, b != nil)
	}
	return cmp.Compare(*a, *b)
}

// _vector_canonPtrInt32 reports whether x, a map key of type *int32, is the key
// that a decode of its projection yields, so that the map of a decode needs no
// other check to keep one entry for the keys of one projection.
func _vector_canonPtrInt32(x *int32) bool {
	return false
}

// _vector_sizeCircle returns the length of the encoding of the Circle that m
// points at.
func _vector_sizeCircle(m *Circle) int {
	n := 0
	if math.Float64bits(m.Radius) != 0 {
		n += 9
	}
	return n
}

// _vector_sizePtrSquare returns the length of the encoding of x, a *Square: its
// presence byte and the value that it points at.
func _vector_sizePtrSquare(x *Square) int {
	if x == nil {
		return 1
	}
	return 1 + wire.SizeBytes(_vector_sizeSquare(x))
}

// _vector_sizeSliceAny returns the length of the encoding of the elements of x,
// a []any.
func _vector_sizeSliceAny(x []any) int {
	n := 0
	for k := range x {
		n += _vector_sizeAny(x[k])
	}
	return n
}

// _vector_putSliceAny writes the encoding of x, a []any, into the end of buf,
// which has room for it, and returns its length. It fails for a value that
// fails to encode, which loc and num locate.
func _vector_putSliceAny(buf []byte, x []any, loc string, num int) (int, error) {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, err := _vector_putAny(buf[:i], x[k], loc, num)
		if err != nil {
			return 0, err
		}
		i -= w
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i, nil
}

// _vector_comparePoint returns -1, 0 or +1 as the map key a sorts before, with
// or after b, two keys of type Point.
func _vector_comparePoint(a, b Point) int {
	if c := cmp.Compare(a.X, b.X); c != 0 {
		return c
	}
	return cmp.Compare(a.Y, b.Y)
}

// _vector_putCircle writes the encoding of the Circle that m points at into the
// end of buf, which has room for it, and returns its length.
func _vector_putCircle(buf []byte, m *Circle) int {
	i := len(buf)
	if math.Float64bits(m.Radius) != 0 {
		i = wire.PutUint64(buf, i, math.Float64bits(m.Radius))
		i = wire.PutTag(buf, i, 1<<3|wire.Fixed64)
	}
	return len(buf) - i
}

// _vector_putPtrSquare writes the encoding of x, a *Square, into the end of
// buf, which has room for it, and returns its length.
func _vector_putPtrSquare(buf []byte, x *Square) int {
	i := len(buf)
	if x != nil {
		w := _vector_putSquare(buf[:i], x)
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _vector_mergeCircle merges the encoding in data, which starts at offset off
// of slab, into the Circle that m points at, as MergeKanon does. The decode
// enters depth levels below m at most.
func _vector_mergeCircle(m *Circle, data []byte, slab string, off, depth int) error {
	var prior uint64
	i := 0
	if i < len(data) && data[i] == 1<<3|wire.Fixed64 {
		at := i
		i++
		prior = 1
		u, n := wire.Uint64(data[i:])
		if n <= 0 {
			return wire.ReadError(n, "Circle.Radius", 1, off+i)
		}
		m.Radius = math.Float64frombits(u)
		i += n
		if !(math.Float64bits(m.Radius) != 0) {
			return wire.AbsentError("Circle.Radius", 1, off+at)
		}
	}
	if i != len(data) {
		return _vector_tagCircle(data, i, prior, off)
	}
	return nil
}

// _vector_readCircle sets the Circle that m points at to the value encoded in
// data and reuses its memory, as DecodeKanon does. data starts at offset off of
// slab, and the decode enters depth levels below the value at most.
func _vector_readCircle(m *Circle, data []byte, slab string, off, depth int) error {
	m.Radius = 0
	return _vector_mergeCircle(m, data, slab, off, depth)
}

// _vector_readPtrSquare decodes the *Square at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. With merge set, the struct merges into the struct that *dst
// points at. data starts at offset off of slab, and the decode enters depth
// levels below the value at most. loc and num locate the field in errors.
func _vector_readPtrSquare(dst **Square, data []byte, slab string, off, depth int, merge bool, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(Square)
		*dst = x
	}
	i := 1
	l, n := wire.Uvarint(data[i:])
	if n <= 0 || uint64(len(data)-i-n) < l {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	if n > 1 && data[i+n-1] == 0 {
		return 0, wire.LongFormError(n, loc, num, off+i)
	}
	i += n
	if depth < 1 {
		return 0, wire.DepthError("Square", 0, off+i)
	}
	{
		var err error
		if merge {
			err = _vector_mergeSquare(x, data[i:i+int(l)], slab, off+i, depth-1)
		} else {
			err = _vector_readSquare(x, data[i:i+int(l)], slab, off+i, depth-1)
		}
		if err != nil {
			return 0, err
		}
	}
	i += int(l)
	return i, nil
}

// _vector_tagPoint returns the error of the canonical decode of Point for the
// tag at data[i], which begins no field after the fields that the decode read
// before it. data starts at offset off of the slab.
func _vector_tagPoint(data []byte, i int, prior uint64, off int) error {
	tag, n := wire.Uvarint(data[i:])
	if n <= 0 {
		return wire.ReadError(n, "Point", 0, off+i)
	}
	if n > 1 && data[i+n-1] == 0 {
		return wire.LongFormError(n, "Point", 0, off+i)
	}
	if tag>>3 == 0 {
		return wire.TagError(tag, "Point", 0, off+i)
	}
	if tag>>3 <= prior {
		return wire.OrderError(tag>>3, prior, "Point", 0, off+i)
	}
	switch tag >> 3 {
	case 1:
		return wire.FormatError(tag, wire.Varint, "Point.X", off+i)
	case 2:
		return wire.FormatError(tag, wire.Varint, "Point.Y", off+i)
	}
	return wire.UnknownFieldError(tag>>3, "Point", 0, off+i)
}

// _vector_readSliceAny appends the elements that data encodes, a []any without
// its length, to *dst. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _vector_readSliceAny(dst *[]any, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	for i := 0; i < len(data); {
		if len(x) < cap(x) {
			x = x[:len(x)+1]
		} else {
			x = append(x, nil)
		}
		last := len(x) - 1
		used, err := _vector_readAny(&x[last], data[i:], slab, off+i, depth-1, false, loc, num)
		if err != nil {
			return err
		}
		i += used
	}
	*dst = x
	return nil
}

// _vector_clonePtrSquare returns a pointer to a copy of the value that x, a
// *Square, points at, and nil for a nil x.
func _vector_clonePtrSquare(x *Square) *Square {
	if x == nil {
		return nil
	}
	return new(*x)
}

// _vector_cloneSliceAny returns a copy of x, a []any, and nil for a nil x.
func _vector_cloneSliceAny(x []any) []any {
	if x == nil {
		return nil
	}
	c := make([]any, len(x))
	for k := range x {
		c[k] = _vector_cloneAny(x[k])
	}
	return c
}

// _vector_sizeSquare returns the length of the encoding of the Square that m
// points at.
func _vector_sizeSquare(m *Square) int {
	n := 0
	if m.Side != 0 {
		n += 1 + wire.SizeUvarint(wire.Zigzag(int64(m.Side)))
	}
	return n
}

// _vector_putSquare writes the encoding of the Square that m points at into the
// end of buf, which has room for it, and returns its length.
func _vector_putSquare(buf []byte, m *Square) int {
	i := len(buf)
	if m.Side != 0 {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(m.Side)))
		i = wire.PutTag(buf, i, 1<<3|wire.Varint)
	}
	return len(buf) - i
}

